   249→      id: typedLog.id,
   250→      importedAt: typedLog.createdAt.toISOString(),
   251→      importedBy: typedLog.user.name || typedLog.user.email,
   252→      strategy,
   253→      statistics,
   254→      success: typedLog.entityType === "BACKUP_IMPORT",
   255→    };
