   307→        name: "data/people.json",
   308→      });
   309→      archive.append(JSON.stringify(data.relationships, null, 2), {
   310→        name: "data/relationships.json",
   311→      });
   312→      archive.append(JSON.stringify(data.users, null, 2), {
   313→        name: "data/users.json",
   314→      });
   315→      archive.append(JSON.stringify(data.suggestions, null, 2), {
   316→        name: "data/suggestions.json",
   317→      });
   318→      archive.append(JSON.stringify(data.settings, null, 2), {
   319→        name: "data/settings.json",
   320→      });
   321→
   322→      if (data.auditLogs) {
   323→        archive.append(JSON.stringify(data.auditLogs, null, 2), {
   324→          name: "data/audit-logs.json",
   325→        });
   326→      }
   327→
   328→      // Add photos
   329→      if (photos.length > 0) {
   330→        addPhotosToBackupArchive(archive, photos);
   331→      } else {
   332→        archive.finalize();
   333→      }
   334→    });
   335→  } catch (error) {
   336→    console.error("Failed to create pre-import backup:", error);
   337→    throw new Error("Failed to create backup before import");
   338→  }
   339→}
   340→
   341→async function addPhotosToBackupArchive(
   342→  archive: archiver.Archiver,
   343→  photos: Array<{ id: string; photoUrl: string | null }>
   344→): Promise<void> {
   345→  for (const person of photos) {
   346→    if (!person.photoUrl) continue;
   347→
   348→    try {
   349→      // Extract the file path from the URL
   350→      const urlParts = person.photoUrl.split("/api/uploads/");
   351→      if (urlParts.length !== 2) continue;
   352→
   353→      const filePath = urlParts[1];
   354→      const storagePath = process.env.STORAGE_LOCAL_PATH || "./data/uploads";
   355→      const fullPath = join(storagePath, filePath);
   356→
   357→      // Read the file
   358→      const fileBuffer = await require("fs/promises").readFile(fullPath);
   359→
   360→      // Extract original filename
   361→      const originalName = filePath.split("-").slice(1).join("-");
   362→
   363→      // Add to archive
   364→      archive.append(fileBuffer, {
   365→        name: `photos/${person.id}/${originalName}`,
   366→      });
   367→    } catch (error) {
   368→      console.warn(`Failed to add photo for person ${person.id}:`, error);
   369→    }
   370→  }
   371→
   372→  archive.finalize();
   373→}
   374→
   375→// Exported for testing
   376→export async function importPhotosCore(
   377→  extractedFiles: Map<string, any>,
   378→  deps: RestoreDependencies
   379→): Promise<number> {
   380→  const storage = deps.getStorageAdapter();
   381→  let importedCount = 0;
   382→
   383→  for (const [filePath, fileBuffer] of extractedFiles.entries()) {
   384→    if (!filePath.startsWith("photos/") || filePath.endsWith("/")) {
   385→      continue;
   386→    }
   387→
   388→    try {
   389→      // Extract person ID and filename from path: photos/{personId}/{filename}
   390→      const pathParts = filePath.split("/");
   391→      if (pathParts.length !== 3) continue;
   392→
   393→      const personId = pathParts[1];
   394→      const filename = pathParts[2];
   395→
   396→      // Check if person exists
   397→      const person = await deps.db.person.findUnique({
   398→        where: { id: personId },
   399→      });
   400→      if (!person) {
   401→        console.warn(`Skipping photo for non-existent person: ${personId}`);
   402→        continue;
   403→      }
   404→
   405→      // Upload photo to storage
   406→      const storedPath = await storage.upload(
   407→        fileBuffer,
   408→        filename,
   409→        "image/jpeg"
   410→      );
   411→      const photoUrl = storage.getUrl(storedPath);
   412→
   413→      // Update person with photo URL
   414→      await deps.db.person.update({
   415→        where: { id: personId },
   416→        data: { photoUrl },
   417→      });
   418→
   419→      importedCount++;
   420→    } catch (error) {
   421→      console.warn(`Failed to import photo ${filePath}:`, error);
   422→    }
   423→  }
   424→
   425→  return importedCount;
   426→}
   427→
   428→// Public API - uses default dependencies (for production use)
   429→export async function validateBackup(
   430→  formData: FormData
   431→): Promise<ValidationResult> {
   432→  return validateBackupCore(formData, defaultDependencies);
   433→}
   434→
   435→export async function importBackup(
   436→  formData: FormData,
   437→  strategy: ConflictResolutionStrategy,
   438→  options: {
   439→    createBackupBeforeImport: boolean;
   440→    importPhotos: boolean;
   441→    importAuditLogs: boolean;
   442→  }
   443→): Promise<ImportResult> {
   444→  return importBackupCore(formData, strategy, options, defaultDependencies);
   445→}
   446→
   447→export async function getImportHistory(): Promise<
   448→  Array<{
   449→    id: string;
   450→    importedAt: string;
   451→    importedBy: string;
   452→    strategy: string;
   453→    statistics: any;
   454→    success: boolean;
   455→  }>
   456→> {
   457→  return getImportHistoryCore(defaultDependencies);
   458→}
