"use client";

import { useState } from "react";
import { useForm, SubmitHandler } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { ImportPreview } from "./import-preview";
import { ValidationResult } from "@/schemas/backup";
import { Loader2, Upload } from "lucide-react";

function isFileListLike(value: unknown): boolean {
  if (typeof window === "undefined") return true;
  if (value === null || value === undefined) return false;
  if (typeof value !== "object") return false;
  const length = (value as { length?: unknown }).length;
  return typeof length === "number" && length > 0;
}

const formSchema = z.object({
  file: z.any().refine((files) => isFileListLike(files), "A file is required."),
});

type FormValues = z.infer<typeof formSchema>;

async function validateBackup(file: File): Promise<ValidationResult> {
  const formData = new FormData();
  formData.append("file", file);

  const response = await fetch("/api/admin/backup/validate", {
    method: "POST",
    body: formData,
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || "Failed to validate backup file.");
  }

  return response.json();
}

export function BackupImport() {
  const { toast } = useToast();
  const [validationResult, setValidationResult] =
    useState<ValidationResult | null>(null);
  const [backupFile, setBackupFile] = useState<File | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<FormValues>({
    resolver: zodResolver(formSchema),
  });

  const mutation = useMutation({
    mutationFn: (file: File) => validateBackup(file),
    onSuccess: (data) => {
      setValidationResult(data);
      toast({
        title: "Validation Successful",
        description: "Review the import preview below.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Validation Failed",
        description: error.message,
        variant: "destructive",
      });
      reset();
    },
  });

  const onSubmit: SubmitHandler<FormValues> = (data) => {
    const file = data.file[0];
    if (file) {
      setBackupFile(file);
      mutation.mutate(file);
    }
  };

  const handleReset = () => {
    setValidationResult(null);
    setBackupFile(null);
    reset();
  };

  if (validationResult && backupFile) {
    return (
      <ImportPreview
        result={validationResult}
        file={backupFile}
        onReset={handleReset}
      />
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div className="space-y-2">
        <Label htmlFor="backup-file">Backup File (.zip)</Label>
        <Input
          id="backup-file"
          type="file"
          accept=".zip"
          {...register("file")}
        />
        {errors.file?.message && (
          <p className="text-sm text-destructive">
            {String(errors.file.message)}
          </p>
        )}
      </div>
      <p className="text-sm text-muted-foreground">
        Importing will add or update data. It is strongly recommended to perform
        a backup first.
      </p>
      <Button type="submit" disabled={mutation.isPending}>
        {mutation.isPending ? (
          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
        ) : (
          <Upload className="mr-2 h-4 w-4" />
        )}
        {mutation.isPending ? "Validating..." : "Validate Backup"}
      </Button>
    </form>
  );
}

import { z } from "zod";

export const backupExportSchema = z.object({
  includePhotos: z.boolean().default(true),
  includeAuditLogs: z.boolean().default(true),
  auditLogDays: z.number().min(1).max(365).default(90),
});

export const backupMetadataSchema = z.object({
  version: z.string(),
  exportedAt: z.string(),
  exportedBy: z.object({
    id: z.string(),
    email: z.string(),
    name: z.string().nullable(),
  }),
  statistics: z.object({
    totalPeople: z.number(),
    totalRelationships: z.number(),
    totalUsers: z.number(),
    totalSuggestions: z.number(),
    totalPhotos: z.number(),
    auditLogDays: z.number(),
    totalAuditLogs: z.number(),
  }),
  dataFiles: z.array(z.string()),
  photoDirectories: z.array(z.string()),
});

// Import schemas
export const conflictResolutionStrategy = z.enum(["skip", "replace", "merge"]);

export const backupValidationSchema = z.object({
  file: z.instanceof(File),
});

export const backupImportSchema = z.object({
  file: z.instanceof(File),
  strategy: conflictResolutionStrategy,
  createBackupBeforeImport: z.boolean().default(true),
  importPhotos: z.boolean().default(true),
  importAuditLogs: z.boolean().default(false),
});

export const conflictSchema = z.object({
  type: z.enum(["person", "user", "relationship", "suggestion", "settings"]),
  action: z.enum(["create", "update"]),
  existingId: z.string().optional(),
  existingData: z.record(z.string(), z.any()).optional(),
  newData: z.record(z.string(), z.any()),
  conflictFields: z.array(z.string()),
  severity: z.enum(["low", "medium", "high"]),
  description: z.string(),
});

export const validationResultSchema = z.object({
  isValid: z.boolean(),
  metadata: backupMetadataSchema,
  conflicts: z.array(conflictSchema),
  statistics: z.object({
    totalConflicts: z.number(),
    conflictsByType: z.record(z.string(), z.number()),
    conflictsBySeverity: z.record(z.string(), z.number()),
  }),
  errors: z.array(z.string()),
  warnings: z.array(z.string()),
});

export const importResultSchema = z.object({
  success: z.boolean(),
  importedAt: z.string(),
  importedBy: z.object({
    id: z.string(),
    email: z.string(),
    name: z.string().nullable(),
  }),
  strategy: conflictResolutionStrategy,
  statistics: z.object({
    peopleImported: z.number(),
    relationshipsImported: z.number(),
    usersImported: z.number(),
    suggestionsImported: z.number(),
    photosImported: z.number(),
    auditLogsImported: z.number(),
    conflictsResolved: z.number(),
    skippedItems: z.number(),
  }),
  backupCreated: z.string().optional(),
  errors: z.array(z.string()),
  warnings: z.array(z.string()),
});

export type BackupExportInput = z.infer<typeof backupExportSchema>;
export type BackupMetadata = z.infer<typeof backupMetadataSchema>;
export type ConflictResolutionStrategy = z.infer<
  typeof conflictResolutionStrategy
>;
export type BackupValidationInput = z.infer<typeof backupValidationSchema>;
export type BackupImportInput = z.infer<typeof backupImportSchema>;
export type Conflict = z.infer<typeof conflictSchema>;
export type ValidationResult = z.infer<typeof validationResultSchema>;
export type ImportResult = z.infer<typeof importResultSchema>;

export const backupValidationPreviewSchema = z.object({
  stats: z.object({
    new: z.object({
      people: z.number(),
      relationships: z.number(),
      users: z.number(),
    }),
  }),
  conflicts: z.object({
    people: z.array(
      z.object({
        data: z.record(z.string(), z.any()), // simplified for frontend
        reason: z.string(),
      })
    ),
    relationships: z.array(
      z.object({
        data: z.record(z.string(), z.any()), // simplified
        reason: z.string(),
      })
    ),
  }),
});

export type BackupValidationPreview = z.infer<
  typeof backupValidationPreviewSchema
>;
